def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most common color is the background; full lines of another
    # color divide the grid into repeated regions.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    row_dividers = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    col_dividers = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
        and grid[0][c] != background
    ]

    def segments(length, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < length:
            result.append((start, length))
        return result

    rows = segments(h, row_dividers)
    cols = segments(w, col_dividers)

    # Pick the region containing the most non-background cells as the
    # pattern, then repeat that pattern in every region.
    best = None
    best_count = -1
    for r0, r1 in rows:
        for c0, c1 in cols:
            count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            if count > best_count:
                best_count = count
                best = (r0, r1, c0, c1)

    r0, r1, c0, c1 = best
    tile = [row[c0:c1] for row in grid[r0:r1]]
    out = [row[:] for row in grid]

    for a, b in rows:
        for x, y in cols:
            if b - a == r1 - r0 and y - x == c1 - c0:
                for i in range(b - a):
                    out[a + i][x:y] = tile[i][:]

    return out
